let state={route:'login',routeHistory:[],lang:localStorage.getItem('medifind-language')||'en',theme:window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light',textSize:localStorage.getItem('medifind-text-size')||'normal',accountType:sessionStorage.getItem('medifind-account-type')||'user',token:localStorage.getItem('medifind-token')||'',guest:false,user:JSON.parse(localStorage.getItem('medifind-user')||'null')||{name:'Guest',email:'',phone:'',role:'customer'},medicine:null,query:'Paracetamol',location:'Jaffna',coords:{lat:9.6658,lng:80.0216},selected:null,quantity:2,tab:'active',reservations:[],pharmacyData:null};
