let activeRequests=0,busyTimer;function setBusy(busy){activeRequests=Math.max(0,activeRequests+(busy?1:-1));let loader=document.querySelector('#globalLoader');if(!loader){loader=document.createElement('div');loader.id='globalLoader';loader.className='global-loader';loader.setAttribute('role','status');loader.setAttribute('aria-live','polite');loader.innerHTML='<span class="loading-spinner" aria-hidden="true"></span><span>Loading…</span>';loader.hidden=true;document.body.append(loader)}if(activeRequests===0){clearTimeout(busyTimer);busyTimer=null;loader.hidden=true;document.body.classList.remove('api-busy');return}if(!busyTimer&&loader.hidden)busyTimer=setTimeout(()=>{busyTimer=null;if(activeRequests>0){loader.hidden=false;document.body.classList.add('api-busy')}},450)}
async function api(path,options={}){const {silent=false,timeout,...requestOptions}=options;let timeoutId,timedOut=false;if(timeout){const controller=new AbortController();timeoutId=setTimeout(()=>{timedOut=true;controller.abort()},timeout);requestOptions.signal=controller.signal}if(!silent)setBusy(true);try{const headers={'Content-Type':'application/json',...(requestOptions.headers||{})};if(state.token)headers.Authorization=`Bearer ${state.token}`;const response=await fetch(`${API_URL}${path}`,{...requestOptions,headers});const data=await response.json().catch(()=>({message:'The server returned an invalid response'}));if(!response.ok)throw Object.assign(new Error(data.message||'Request failed'),{details:data.details||[]});return data}catch(error){if(timedOut)throw new Error('The request took too long. Please try again.');if(error.name==='TypeError')throw new Error('Unable to connect to MediFind. Check the backend and your internet connection, then try again.');throw error}finally{clearTimeout(timeoutId);if(!silent)setBusy(false)}}
async function apiCsv(path,csv,{fileName='inventory.csv'}={}){setBusy(true);try{const response=await fetch(`${API_URL}${path}`,{method:'POST',headers:{'Content-Type':'text/csv',Authorization:`Bearer ${state.token}`,'X-File-Name':encodeURIComponent(fileName)},body:csv});const data=await response.json().catch(()=>({message:'The server returned an invalid response'}));if(!response.ok)throw Object.assign(new Error(data.message||'CSV import failed'),{details:data.errors||[]});return data}finally{setBusy(false)}}
const pharmacyViewModel=item=>{const stock=item.availability||{},medicine=item.medicine||{};return{id:item._id,name:item.pharmacyName,address:item.address,city:item.city,lat:item.latitude,lng:item.longitude,phone:item.contactNumber,hours:item.openingHours,rating:item.rating||0,reviews:item.reviews||0,distance:item.distance==null?null:Number(item.distance),status:stock.availabilityStatus||'out',qty:Number(stock.quantity||0),unitPrice:stock.unitPrice,currency:stock.currency||'LKR',notes:stock.notes||'',medicineId:medicine._id||stock.medicineId||state.medicine?._id,medicineName:medicine.name||state.query,genericName:medicine.genericName||'',dosage:medicine.dosage||'',form:medicine.form||'',manufacturer:medicine.manufacturer||'',requiresPrescription:Boolean(medicine.requiresPrescription),lastUpdated:stock.lastUpdated}};
async function loadPharmacies({nearby=false,timeout}={}){const params=new URLSearchParams({medicine:state.query.trim()});if(nearby){params.set('lat',state.coords.lat);params.set('lng',state.coords.lng);params.set('radius','500')}else params.set('location',state.location.trim());const data=await api(`/pharmacies/${nearby?'nearby?':'?'}${params}`,{timeout});pharmacies=data.pharmacies.map(pharmacyViewModel);state.filteredPharmacies=[...pharmacies];state.medicine=data.pharmacies.find(item=>item.medicine)?.medicine||null;state.selected=pharmacies[0]||null;return pharmacies}
async function loadReservations(){if(!state.token||state.guest)return[];const data=await api('/reservations/user');state.reservations=data.reservations.map(item=>({id:item._id,reservationId:item.reservationId,medicine:item.medicineId?.name||'Medicine',medicineId:item.medicineId?._id,pharmacy:item.pharmacyId?.pharmacyName||'Pharmacy',pharmacyId:item.pharmacyId?._id,time:new Date(item.collectionTime).toLocaleString(),collectedTime:item.status==='collected'?new Date(item.collectedAt||item.updatedAt).toLocaleString():null,status:item.status,reviewRating:item.reviewRating||null,reviewedAt:item.reviewedAt||null}));return state.reservations}
async function loadPharmacyDashboard(){const [owned,reservations]=await Promise.all([api('/pharmacies/mine'),api('/reservations/pharmacy')]);state.pharmacyData={pharmacies:owned.pharmacies,inventory:owned.inventory,reservations:reservations.reservations};return state.pharmacyData}
