function applyTranslations(){if(state.lang==='en')return;const map=translations[state.lang],entries=Object.entries(map).sort((a,b)=>b[0].length-a[0].length);const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const clean=node.nodeValue.trim();if(map[clean])node.nodeValue=node.nodeValue.replace(clean,map[clean]);else{const match=entries.find(([source])=>clean.endsWith(source));if(match)node.nodeValue=node.nodeValue.replace(match[0],match[1])}}document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(input=>{if(map[input.placeholder])input.placeholder=map[input.placeholder]});document.querySelectorAll('[aria-label]').forEach(element=>{const label=element.getAttribute('aria-label');if(map[label])element.setAttribute('aria-label',map[label])})}
