const translationNodeState=new WeakMap(),translationAttributeState=new WeakMap();
function translateInterfaceValue(value,map,entries){
  const leading=value.match(/^\s*/)?.[0]||'',trailing=value.match(/\s*$/)?.[0]||'',clean=value.trim();
  if(!clean)return value;
  if(map[clean])return `${leading}${map[clean]}${trailing}`;
  let translated=value;
  for(const [source,target] of entries){if((source.includes(' ')||source.length>=8)&&translated.includes(source))translated=translated.split(source).join(target)}
  return translated;
}
applyTranslations=function(){
  document.documentElement.lang=state.lang;
  document.querySelectorAll('[data-lang]').forEach(button=>{button.classList.toggle('active',button.dataset.lang===state.lang);button.setAttribute('aria-pressed',button.dataset.lang===state.lang)});
  const map=translations[state.lang]||{},entries=Object.entries(map).sort((a,b)=>b[0].length-a[0].length),walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(node){return node.parentElement?.closest('script,style,input,textarea,[data-no-translate]')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});
  let node;
  while(node=walker.nextNode()){
    const current=node.nodeValue,record=translationNodeState.get(node);
    if(!record||current!==record.last)translationNodeState.set(node,{source:current,last:current});
    const active=translationNodeState.get(node),next=state.lang==='en'?active.source:translateInterfaceValue(active.source,map,entries);
    node.nodeValue=next;active.last=next;
  }
  document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(element=>{
    let records=translationAttributeState.get(element);if(!records){records={};translationAttributeState.set(element,records)}
    for(const attribute of ['placeholder','aria-label','title']){
      if(!element.hasAttribute(attribute))continue;
      const current=element.getAttribute(attribute),record=records[attribute];
      if(!record||current!==record.last)records[attribute]={source:current,last:current};
      const active=records[attribute],next=state.lang==='en'?active.source:translateInterfaceValue(active.source,map,entries);
      element.setAttribute(attribute,next);active.last=next;
    }
  });
};
function paintUserAvatar(element){if(!element)return;if(state.user.profilePhoto){element.textContent='';element.style.backgroundImage=`url("${state.user.profilePhoto}")`;element.classList.add('has-photo')}else{element.style.backgroundImage='';element.textContent=(state.user.name||'U').charAt(0).toUpperCase();element.classList.remove('has-photo')}}
function updateSessionUI(){document.body.classList.toggle('dark-mode',state.theme==='dark');document.body.classList.remove('text-large','text-xlarge');if(state.textSize!=='normal')document.body.classList.add(`text-${state.textSize}`);const profile=document.querySelector('.profile-btn'),guestSignIn=document.querySelector('.guest-signin');if(profile){profile.classList.toggle('hidden',state.guest);profile.querySelector('.profile-name').textContent=state.user.name;paintUserAvatar(profile.querySelector('.avatar'))}if(guestSignIn)guestSignIn.classList.toggle('visible',state.guest);if(state.route==='profile'&&!state.guest){const fields=document.querySelectorAll('#profileForm input');if(fields[0])fields[0].value=state.user.name;if(fields[1])fields[1].value=state.user.email;if(fields[2])fields[2].value=state.user.phone;const cardName=document.querySelector('.profile-card h2');if(cardName)cardName.textContent=state.user.name;paintUserAvatar(document.querySelector('.profile-card .avatar'))}}
function ensureThemeToggle(){const topbar=document.querySelector('.welcome-topbar');if(!topbar)return;const language=topbar.querySelector('.welcome-language');const tools=document.createElement('div');tools.className='welcome-tools';const size=document.createElement('button');size.className='theme-toggle text-size-toggle';size.id='textSizeToggle';size.type='button';size.setAttribute('aria-label','Change text size');size.title='Change text size';size.innerHTML=`<span aria-hidden="true">A${state.textSize==='normal'?'':state.textSize==='large'?'+':'++'}</span><span>${state.textSize==='normal'?'Text size':state.textSize==='large'?'Large':'Extra large'}</span>`;const theme=document.createElement('button');theme.className='theme-toggle';theme.id='themeToggle';theme.type='button';theme.setAttribute('aria-label','Switch color theme');theme.innerHTML=`<span>${state.theme==='dark'?'☀':'☾'}</span><span>${state.theme==='dark'?'Light':'Dark'}</span>`;if(language){tools.append(size,theme,language);topbar.append(tools)}}
function updateNotificationUI(){const bell=document.querySelector('.notification-btn');if(!bell)return;bell.classList.toggle('hidden',state.guest||state.route==='help'||!state.token);const owner=state.user?.role==='pharmacyOwner',items=owner?(state.pharmacyData?.reservations||[]):state.reservations,count=owner?items.filter(item=>item.status==='pending').length:items.filter(item=>['confirmed','ready'].includes(item.status)).length,badge=bell.querySelector('b');badge.textContent=count>99?'99+':String(count);badge.hidden=count===0;bell.classList.toggle('has-notifications',count>0);bell.setAttribute('aria-label',count?`${count} ${owner?'new customer reservation':'accepted reservation'} notification${count===1?'':'s'}`:'No new notifications');bell.title=bell.getAttribute('aria-label');const existing=document.querySelector('.reservation-accepted-banner');if(existing)existing.remove();if(!owner&&count&&state.route==='home'){const banner=document.createElement('button');banner.type='button';banner.className='reservation-accepted-banner card';banner.innerHTML=`<span class="accepted-check">✓</span><span><strong>${count===1?'Your reservation was accepted':'Your reservations were updated'}</strong><small>${count} reservation${count===1?' is':'s are'} confirmed or ready. View details and collection status.</small></span><span>View reservations →</span>`;banner.onclick=async()=>{await loadReservations();go('reservations')};document.querySelector('.home-hero')?.after(banner)}}
function updateGlobalControls(){document.querySelectorAll('.text-size-toggle').forEach(button=>{button.querySelector('span:first-child').textContent=`A${state.textSize==='normal'?'':state.textSize==='large'?'+':'++'}`;const label=button.querySelector('span:last-child');if(label)label.textContent=state.textSize==='normal'?'Text size':state.textSize==='large'?'Large':'Extra large'});document.querySelectorAll('.theme-toggle').forEach(button=>{button.querySelector('span:first-child').textContent=state.theme==='dark'?'☀':'☾';const label=button.querySelector('span:last-child');if(label)label.textContent=state.theme==='dark'?'Light':'Dark'});const back=document.querySelector('#backButton');if(back)back.disabled=state.routeHistory.length===0}
function updateRoleUI(){const owner=state.user?.role==='pharmacyOwner',nav=document.querySelector('.site-header nav');if(nav)nav.classList.toggle('role-hidden',owner);const profile=document.querySelector('.profile-btn');if(profile&&owner){profile.classList.remove('hidden');profile.dataset.route='profile'}let logout=document.querySelector('.owner-logout');if(owner&&!logout){logout=document.createElement('button');logout.className='header-tool owner-logout';logout.id='logout';logout.textContent='Logout';document.querySelector('.header-actions')?.insertBefore(logout,document.querySelector('#menuBtn'))}else if(!owner)logout?.remove()}
function setupPharmacyRegistration(){if(state.route!=='pharmacy'||state.pharmacyData?.pharmacies?.length)return;const notice=document.querySelector('.notice');if(!notice)return;notice.innerHTML=`<h2>Register your pharmacy</h2><p>Connect a pharmacy profile to begin managing stock and reservations.</p><form id="pharmacyRegistrationForm" class="pharmacy-registration"><div class="field"><label>Pharmacy name</label><input name="pharmacyName" required></div><div class="field"><label>Address</label><input name="address" required></div><div class="field"><label>City</label><input name="city" value="Jaffna" required></div><div class="field"><label>Contact number</label><input name="contactNumber" required></div><div class="field"><label>Opening hours</label><input name="openingHours" value="Mon–Sun: 7:00 AM–9:00 PM" required></div><div class="field"><label>Latitude</label><input name="latitude" type="number" step="any" value="9.6658" required></div><div class="field"><label>Longitude</label><input name="longitude" type="number" step="any" value="80.0216" required></div><button class="btn primary">Register pharmacy</button></form>`}
function setupPharmacyCsvImport(){if(state.route!=='pharmacy'||!state.pharmacyData?.pharmacies?.length)return;const stats=document.querySelector('.dashboard-stats');if(!stats||document.querySelector('#csvInventoryForm'))return;const pharmacy=state.pharmacyData.pharmacies[0],panel=document.createElement('section');panel.className='csv-import-card card';panel.innerHTML=`<div class="csv-import-copy"><span class="eyebrow">Bulk inventory update</span><h2>Upload medicine CSV</h2><p>Upload new medicines or update existing medicine details, quantity and price for <strong>${pharmacy.pharmacyName}</strong>.</p><a class="template-link" href="templates/pharmacy-inventory-upload.csv" download>↓ Download CSV template</a></div><form id="csvInventoryForm"><input type="hidden" name="pharmacyId" value="${pharmacy._id}"><label class="csv-dropzone" for="inventoryCsv"><span class="csv-icon">⇧</span><strong>Choose a CSV file</strong><small>Maximum 5 MB · CSV only</small><input id="inventoryCsv" name="inventoryCsv" type="file" accept=".csv,text/csv" required></label><div id="csvFileName" class="csv-filename">No file selected</div><button class="btn primary" type="submit">Import and update inventory</button></form><div id="csvImportResult" class="csv-result" aria-live="polite"></div>`;stats.before(panel);panel.querySelector('input[type=file]').onchange=e=>{panel.querySelector('#csvFileName').textContent=e.target.files[0]?.name||'No file selected'}}
function setupPharmacyDetailsEditor(){if(state.route!=='pharmacy'||!state.pharmacyData?.pharmacies?.length)return;const stats=document.querySelector('.dashboard-stats');if(!stats||document.querySelector('#pharmacyDetailsForm'))return;const p=state.pharmacyData.pharmacies[0],panel=document.createElement('details');panel.className='pharmacy-details-editor card';panel.innerHTML=`<summary><span><strong>Pharmacy details</strong><small>${p.address} · ${p.contactNumber}</small></span><span class="btn">Edit details</span></summary><form id="pharmacyDetailsForm" class="pharmacy-registration"><input type="hidden" name="pharmacyId" value="${p._id}"><div class="field"><label>Pharmacy name</label><input name="pharmacyName" value="${p.pharmacyName}" required></div><div class="field"><label>Address</label><input name="address" value="${p.address}" required></div><div class="field"><label>City</label><input name="city" value="${p.city}" required></div><div class="field"><label>Contact number</label><input name="contactNumber" value="${p.contactNumber}" required></div><div class="field"><label>Opening hours</label><input name="openingHours" value="${p.openingHours}" required></div><div class="field"><label>Latitude</label><input name="latitude" type="number" step="any" value="${p.latitude}" required></div><div class="field"><label>Longitude</label><input name="longitude" type="number" step="any" value="${p.longitude}" required></div><button class="btn primary" type="submit">Save pharmacy details</button></form>`;stats.before(panel)}
function enhanceInventoryDisplay(){if(state.route!=='pharmacy')return;document.querySelectorAll('.stock-row').forEach((row,index)=>{const item=state.pharmacyData?.inventory?.[index],medicine=item?.medicineId,summary=row.querySelector('div');if(!medicine||!summary||summary.querySelector('.medicine-meta'))return;const meta=document.createElement('span');meta.className='medicine-meta';meta.innerHTML=`<small>${medicine.genericName||''}${medicine.category?` · ${medicine.category}`:''}${medicine.form?` · ${medicine.form}`:''}</small><small>${medicine.manufacturer||''}${medicine.requiresPrescription?' · Prescription required':''}</small>${item.unitPrice!=null?`<span class="stock-price">${item.currency||'LKR'} ${Number(item.unitPrice).toFixed(2)}</span>`:''}<button class="edit-medicine" type="button" data-index="${index}">Edit all details</button>`;summary.append(meta)})}
function openMedicineEditor(index){const item=state.pharmacyData?.inventory?.[index],m=item?.medicineId,p=state.pharmacyData?.pharmacies?.[0];if(!item||!m||!p)return;document.querySelector('.medicine-edit-overlay')?.remove();const overlay=document.createElement('div');overlay.className='medicine-edit-overlay';overlay.innerHTML=`<form id="medicineEditForm" class="medicine-edit-modal card"><div class="modal-heading"><div><span class="eyebrow">Inventory editor</span><h2>Edit ${m.name}</h2></div><button class="modal-close" type="button" aria-label="Close">×</button></div><input type="hidden" name="pharmacyId" value="${p._id}"><input type="hidden" name="medicineId" value="${m._id}"><div class="medicine-edit-grid"><div class="field"><label>Medicine name</label><input name="name" value="${m.name||''}" required></div><div class="field"><label>Generic name</label><input name="genericName" value="${m.genericName||''}" required></div><div class="field"><label>Category</label><input name="category" value="${m.category||''}" required></div><div class="field"><label>Dosage</label><input name="dosage" value="${m.dosage||''}"></div><div class="field"><label>Form</label><input name="form" value="${m.form||''}" placeholder="Tablet, capsule, syrup"></div><div class="field"><label>Manufacturer</label><input name="manufacturer" value="${m.manufacturer||''}"></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="0" value="${item.quantity}" required></div><div class="field"><label>Unit price</label><input name="unitPrice" type="number" min="0" step="0.01" value="${item.unitPrice??''}"></div><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="${item.currency||'LKR'}"></div><label class="prescription-check"><input name="requiresPrescription" type="checkbox" ${m.requiresPrescription?'checked':''}> Prescription required</label><div class="field full"><label>Description</label><textarea name="description" rows="3">${m.description||''}</textarea></div><div class="field full"><label>Pharmacy notes</label><textarea name="notes" rows="2">${item.notes||''}</textarea></div></div><div class="modal-actions"><button class="btn modal-close" type="button">Cancel</button><button class="btn primary" type="submit">Save medicine changes</button></div></form>`;document.body.append(overlay);overlay.querySelectorAll('.modal-close').forEach(button=>button.onclick=()=>overlay.remove())}
async function loadPublicStoreInventory(){if(state.route!=='details'||!state.selected?.id)return;const grid=document.querySelector('.details-grid');if(!grid)return;let section=document.querySelector('#storeInventory');if(!section){section=document.createElement('section');section.id='storeInventory';section.className='store-inventory';section.innerHTML='<div class="store-inventory-heading"><div><span class="eyebrow">Live store inventory</span><h2>All medicines at this pharmacy</h2></div><span class="muted">Loading current stock…</span></div>';grid.after(section)}try{const data=await api(`/pharmacies/${state.selected.id}`),items=data.inventory||[];if(state.route!=='details'||state.selected?.id!==data.pharmacy._id)return;section.innerHTML=`<div class="store-inventory-heading"><div><span class="eyebrow">Live store inventory</span><h2>All medicines at ${data.pharmacy.pharmacyName}</h2></div><span class="inventory-count">${items.length} medicines</span></div><div class="store-medicine-grid">${items.map(item=>{const medicine=item.medicineId||{};return `<article class="store-medicine card"><div class="store-medicine-top"><span class="medicine-symbol">💊</span><span class="status ${item.availabilityStatus}">${statusText[item.availabilityStatus]}</span></div><h3>${medicine.name||'Medicine'} <small>${medicine.dosage||''}</small></h3><p>${medicine.genericName||''}${medicine.form?` · ${medicine.form}`:''}</p><dl><div><dt>Category</dt><dd>${medicine.category||'—'}</dd></div><div><dt>Manufacturer</dt><dd>${medicine.manufacturer||'—'}</dd></div><div><dt>Quantity</dt><dd>${item.quantity}</dd></div><div><dt>Price</dt><dd>${item.unitPrice!=null?`${item.currency||'LKR'} ${Number(item.unitPrice).toFixed(2)}`:'Ask pharmacy'}</dd></div></dl>${medicine.requiresPrescription?'<span class="prescription-badge">Prescription required</span>':''}${item.notes?`<small class="store-note">${item.notes}</small>`:''}<small class="muted">Updated ${new Date(item.lastUpdated).toLocaleString()}</small></article>`}).join('')||'<div class="empty card">This pharmacy has not uploaded medicines yet.</div>'}</div>`}catch(error){section.innerHTML=`<div class="notice">Unable to load pharmacy inventory: ${error.message}</div>`}}
function go(route,remember=true){if(remember&&route!==state.route)state.routeHistory.push(state.route);state.route=route;header.classList.toggle('hidden',['login','register'].includes(route));document.querySelector('nav')?.classList.remove('open');render();scrollTo(0,0)}
