document.addEventListener('submit',async e=>{const form=e.target;if(!['loginForm','registerForm','searchForm','reservationForm','profileForm'].includes(form.id)&&!form.matches('[data-stock]'))return;e.preventDefault();e.stopImmediatePropagation();const submit=form.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{if(form.id==='loginForm'){const payload={email:form.querySelector('input[type="email"]').value.trim(),password:form.querySelector('input[type="password"]').value,role:state.accountType==='pharmacy'?'pharmacyOwner':'customer'};const data=await api('/auth/login',{method:'POST',body:JSON.stringify(payload)});state.token=data.token;state.user=data.user;state.guest=false;localStorage.setItem('medifind-token',data.token);localStorage.setItem('medifind-user',JSON.stringify(data.user));if(data.user.role==='pharmacyOwner'){await loadPharmacyDashboard();go('pharmacy')}else{await Promise.all([loadPharmacies(),loadReservations()]);go('home')}}else if(form.id==='registerForm'){const values=Object.fromEntries(new FormData(form));const data=await api('/auth/register',{method:'POST',body:JSON.stringify({...values,role:state.accountType==='pharmacy'?'pharmacyOwner':'customer',preferredLanguage:state.lang})});state.token=data.token;state.user=data.user;localStorage.setItem('medifind-token',data.token);localStorage.setItem('medifind-user',JSON.stringify(data.user));if(data.user.role==='pharmacyOwner'){state.pharmacyData={pharmacies:[],inventory:[],reservations:[]};go('pharmacy')}else{await loadPharmacies();go('home')}}else if(form.id==='searchForm'){state.query=form.querySelector('#medicineSearch').value||'Paracetamol';await loadPharmacies();go('pharmacies')}else if(form.id==='reservationForm'){if(!state.token)throw new Error('Please sign in to reserve medicine');const selection=form.querySelector('#collection').value;const collectionTime=new Date(Date.now()+(selection.startsWith('Tomorrow')?26:selection.includes('8:00')?8:6)*60*60*1000);const data=await api('/reservations',{method:'POST',body:JSON.stringify({pharmacyId:state.selected.id,medicineId:state.selected.medicineId||state.medicine?._id,quantity:state.quantity,collectionTime})});state.lastReservation=data.reservation;await loadReservations();go('confirmed')}else if(form.id==='profileForm'){const inputs=form.querySelectorAll('input');const data=await api('/users/profile',{method:'PUT',body:JSON.stringify({name:inputs[0].value,phone:inputs[2].value,preferredLanguage:state.lang})});state.user=data.user;localStorage.setItem('medifind-user',JSON.stringify(data.user));toast('Profile changes saved');render()}else if(form.matches('[data-stock]')){const values=Object.fromEntries(new FormData(form));await api(`/pharmacies/${values.pharmacyId}/stock`,{method:'PUT',body:JSON.stringify({medicineId:values.medicineId,quantity:Number(values.quantity)})});await loadPharmacyDashboard();toast('Stock updated');render()}}catch(error){toast(error.message)}finally{if(submit)submit.disabled=false}},true);
document.addEventListener('submit',async e=>{
  if(e.target.id!=='pharmacyRegistrationForm')return;
  e.preventDefault();e.stopImmediatePropagation();
  const form=e.target,button=form.querySelector('button');button.disabled=true;
  try{
    const values=Object.fromEntries(new FormData(form));values.latitude=Number(values.latitude);values.longitude=Number(values.longitude);
    const created=await api('/pharmacies',{method:'POST',body:JSON.stringify(values)});
    state.pharmacyData={pharmacies:[created.pharmacy],inventory:[],reservations:[]};
    await loadPharmacyDashboard();
    if(!state.pharmacyData.pharmacies.length)state.pharmacyData.pharmacies=[created.pharmacy];
    toast(created.message||'Pharmacy registered successfully');render();
  }catch(error){toast(error.message);button.disabled=false}
},true);
document.addEventListener('submit',async e=>{
  if(e.target.id!=='csvInventoryForm')return;
  e.preventDefault();e.stopImmediatePropagation();
  const form=e.target,file=form.inventoryCsv.files[0],button=form.querySelector('button[type="submit"]'),result=form.parentElement.querySelector('#csvImportResult');
  if(!file)return;
  if(file.size>5*1024*1024){toast('CSV file must be 5 MB or smaller');return}
  button.disabled=true;button.textContent='Importing…';result.className='csv-result';result.textContent='Validating and updating inventory…';
  try{
    const response=await apiCsv(`/pharmacies/${form.pharmacyId.value}/import-inventory`,await file.text());
    result.className='csv-result success';
    result.innerHTML=`<strong>Import completed</strong><span>${response.imported} medicines processed · ${response.inserted} added · ${response.updated} updated</span>`;
    await loadPharmacyDashboard();toast('Medicine inventory updated from CSV');setTimeout(render,900);
  }catch(error){
    result.className='csv-result error';
    result.innerHTML=`<strong>Import failed</strong><span>${error.message}</span>${error.details?.length?`<ul>${error.details.slice(0,8).map(item=>`<li>Row ${item.row}: ${item.message}</li>`).join('')}</ul>`:''}`;
    toast(error.message);button.disabled=false;button.textContent='Import and update inventory';
  }
},true);
