// Window capture runs before the legacy document handler. Pharmacy signup is
// completed atomically with its store profile so the next login always opens
// a populated dashboard instead of asking the owner to register again.
window.addEventListener('submit',async event=>{
  const form=event.target;
  if(form.id!=='registerForm'||state.accountType!=='pharmacy')return;
  event.preventDefault();event.stopImmediatePropagation();
  const button=form.querySelector('button');button.disabled=true;
  try{
    const values=Object.fromEntries(new FormData(form));
    const pharmacy={pharmacyName:values.pharmacyName,address:values.address,city:values.city,contactNumber:values.contactNumber,openingHours:values.openingHours,latitude:Number(values.latitude),longitude:Number(values.longitude)};
    ['pharmacyName','address','city','contactNumber','openingHours','latitude','longitude'].forEach(key=>delete values[key]);
    const data=await api('/auth/register',{method:'POST',body:JSON.stringify({...values,role:'pharmacyOwner',preferredLanguage:state.lang,pharmacy})});
    state.token=data.token;state.user=data.user;state.guest=false;
    localStorage.setItem('medifind-token',data.token);localStorage.setItem('medifind-user',JSON.stringify(data.user));
    await loadPharmacyDashboard();go('pharmacy');
  }catch(error){toast(error.message);button.disabled=false}
},true);

