function setupInventorySearch(){
  if(state.route!=='pharmacy')return;
  const section=document.querySelector('#pharmacyInventory'),list=section?.querySelector('.result-list');
  if(!section||!list||section.querySelector('#inventorySearchForm'))return;
  const rows=[...list.querySelectorAll('.stock-row')],form=document.createElement('form');
  form.id='inventorySearchForm';form.className='inventory-search';form.setAttribute('role','search');
  form.innerHTML=`<label class="sr-only" for="inventorySearchInput">Search inventory medicines</label><input id="inventorySearchInput" class="search-input" type="search" autocomplete="off" placeholder="Search by medicine, generic name, category, or manufacturer"><button class="btn primary" type="submit">Search inventory</button><span class="inventory-search-count" aria-live="polite">${rows.length} medicines shown</span>`;
  const empty=document.createElement('div');empty.className='inventory-search-empty card';empty.textContent='No inventory medicines match your search.';empty.hidden=true;
  section.querySelector('h2')?.after(form);list.after(empty);
  const input=form.querySelector('#inventorySearchInput'),count=form.querySelector('.inventory-search-count');
  const filter=()=>{const query=input.value.trim().toLocaleLowerCase(),visible=rows.filter(row=>{const match=!query||row.textContent.toLocaleLowerCase().includes(query);row.hidden=!match;return match}).length;count.textContent=`${visible} medicines shown`;empty.hidden=visible!==0;applyTranslations()};
  input.addEventListener('input',filter);form.addEventListener('submit',event=>{event.preventDefault();filter();input.focus()});
}
initGoogleMap=async function(){
  const el=document.querySelector('.map');if(!el)return;
  el.id='googleMap';el.innerHTML='<div class="map-loading"><strong>Loading nearest registered pharmacies…</strong><span>Calculating from your live location.</span></div>';
  try{await loadGoogleMapsApi()}catch(error){el.innerHTML=`<div class="map-error"><strong>${error.message}</strong><br>Add <code>MEDIFIND_GOOGLE_MAPS_API_KEY</code> in <code>frontend/config.js</code>.</div>`;return}
  const valid=pharmacies.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lng));
  if(!valid.length){el.innerHTML='<div class="map-error"><strong>No available registered pharmacies found nearby.</strong><br>Try another medicine or increase the search area.</div>';return}
  const user=state.liveCoords;
  const map=new google.maps.Map(el,{center:user||{lat:valid[0].lat,lng:valid[0].lng},zoom:13,mapTypeControl:false,streetViewControl:false,fullscreenControl:true});
  const bounds=new google.maps.LatLngBounds(),markers={},directionsService=new google.maps.DirectionsService(),directionsRenderer=new google.maps.DirectionsRenderer({map,suppressMarkers:true,preserveViewport:false,polylineOptions:{strokeColor:'#0759e6',strokeOpacity:.9,strokeWeight:6}});
  const summary=document.createElement('div');summary.className='route-summary';summary.innerHTML='<strong>Select a pharmacy</strong><span>Route information will appear here.</span>';el.append(summary);
  if(user){const marker=new google.maps.Marker({position:user,map,title:'Your live location',zIndex:999,icon:{path:google.maps.SymbolPath.CIRCLE,scale:10,fillColor:'#0759e6',fillOpacity:1,strokeColor:'#fff',strokeWeight:4}});marker.addListener('click',()=>new google.maps.InfoWindow({content:'<strong>Your live location</strong>'}).open({map,anchor:marker}));bounds.extend(user)}
  const showRoute=p=>{
    const entry=markers[p.id];entry?.info.open({map,anchor:entry.marker});
    document.querySelectorAll('.map-list .map-card').forEach(card=>card.classList.toggle('selected',card.dataset.id===String(p.id)));
    if(!user){summary.innerHTML='<strong>Live location required</strong><span>Allow location access to calculate the path.</span>';map.panTo({lat:p.lat,lng:p.lng});map.setZoom(16);return}
    summary.innerHTML=`<strong>Route to ${p.name}</strong><span>Calculating driving path…</span>`;
    directionsService.route({origin:user,destination:{lat:p.lat,lng:p.lng},travelMode:google.maps.TravelMode.DRIVING},(result,status)=>{
      if(status==='OK'){directionsRenderer.setDirections(result);const leg=result.routes[0].legs[0];summary.innerHTML=`<strong>${p.name}</strong><span>${leg.distance.text} · about ${leg.duration.text} by road</span>`}
      else{summary.innerHTML=`<strong>${p.name}</strong><span>Road route unavailable. Use the Directions link.</span>`;toast(`Could not calculate route: ${status}`)}
    })
  };
  valid.forEach(p=>{const position={lat:p.lat,lng:p.lng},marker=new google.maps.Marker({position,map,title:p.name,label:{text:'+',color:'#fff',fontSize:'18px',fontWeight:'800'},icon:{path:google.maps.SymbolPath.CIRCLE,scale:18,fillColor:p.status==='low'?'#e98b00':'#159b52',fillOpacity:1,strokeColor:'#fff',strokeWeight:4}}),info=new google.maps.InfoWindow({content:`<div class="map-popup"><strong>${p.name}</strong><span>${p.medicineName}${p.dosage?` · ${p.dosage}`:''}</span><span class="status ${p.status}">● ${statusText[p.status]}</span><small>${p.distance!=null?`${p.distance} km straight-line · `:''}${p.qty} available</small><div><a href="https://www.google.com/maps/dir/?api=1&origin=${user?`${user.lat},${user.lng}`:''}&destination=${p.lat},${p.lng}&travelmode=driving" target="_blank" rel="noopener">Open directions ↗</a></div></div>`});markers[p.id]={marker,info};marker.addListener('click',()=>showRoute(p));bounds.extend(position)});
  document.querySelectorAll('.map-list .map-card').forEach(card=>card.onclick=()=>{const p=valid.find(item=>String(item.id)===card.dataset.id);if(p)showRoute(p)});
  map.fitBounds(bounds,70);
  if(user&&valid[0])setTimeout(()=>showRoute(valid[0]),350);
};

let notificationRefreshRunning=false;
async function refreshReservationNotifications(){
  if(notificationRefreshRunning||document.hidden||!state.token||state.guest)return;
  notificationRefreshRunning=true;
  try{
    const owner=state.user?.role==='pharmacyOwner',before=owner?(state.pharmacyData?.reservations||[]):state.reservations,beforeSignature=before.map(item=>`${item._id||item.id}:${item.status}`).join('|');
    if(owner)await loadPharmacyDashboard();else await loadReservations();
    const after=owner?(state.pharmacyData?.reservations||[]):state.reservations,afterSignature=after.map(item=>`${item._id||item.id}:${item.status}`).join('|'),count=owner?after.filter(item=>item.status==='pending').length:after.filter(item=>['confirmed','ready'].includes(item.status)).length;
    if(state.notificationCount!=null&&count>state.notificationCount)toast(owner?'A new customer reservation was received':'Your reservation was accepted by the pharmacy');
    state.notificationCount=count;updateNotificationUI();
    if(!owner&&state.route==='reservations'&&beforeSignature!==afterSignature)render();
  }catch{}finally{notificationRefreshRunning=false}
}
setInterval(refreshReservationNotifications,15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshReservationNotifications()});

