  const remove=event.target.closest('.delete-medicine');if(remove){event.preventDefault();event.stopImmediatePropagation();const item=state.pharmacyData.inventory[Number(remove.dataset.index)],pharmacy=state.pharmacyData.pharmacies[0];if(!confirm(`Remove ${item.medicineId?.name||'this medicine'} from your inventory? This cannot be undone.`))return;try{await api(`/pharmacies/${pharmacy._id}/medicines/${item.medicineId._id}`,{method:'DELETE'});await loadPharmacyDashboard();toast('Medicine removed from inventory');render()}catch(error){toast(error.message)}return}
  const cancel=event.target.closest('.cancel-res');if(cancel){event.preventDefault();event.stopImmediatePropagation();if(!confirm('Cancel this reservation? The reserved stock will be returned to the pharmacy.'))return;try{const reservation=state.reservations[Number(cancel.dataset.i)];await api(`/reservations/${reservation.id}`,{method:'DELETE'});await loadReservations();toast('Reservation cancelled and stock restored');render()}catch(error){toast(error.message)}return}
